import React, { useState } from 'react';
import toast from 'react-hot-toast';

import MethodSelector from "../components/lab3/MethodSelector";
import { Header } from "./Header";
import FunctionSelector from "../components/lab3/FunctionSelector";
import IntegrationForm from "../components/lab3/IntegrationForm";
import IntegrationChart from "../components/lab3/IntegrationChart";
import ResultsTable from "../components/lab3/ResultsTable";
import { FileUpload } from "../components/common/FileUpload";

import { lab3Api } from '../services/api';
import { IntegrationRequest, IntegrationResponse } from '../types';

const IntegrationPage: React.FC = () => {
    const [request, setRequest] = useState<IntegrationRequest>({
        functionId: 1,
        methodId: 5,
        a: 12,
        b: 124,
        epsilon: 0.00001
    });

    const [response, setResponse] = useState<IntegrationResponse | null>(null);
    const [loading, setLoading] = useState(false);

    const handleCalculate = async () => {
        setLoading(true);
        // ВАЖНО: сбрасываем ответ перед новым запросом,
        // чтобы график не пытался рендериться со старыми точками под новые границы
        setResponse(null);

        try {
            const res = await lab3Api.calculate(request);

            // Проверка на наличие данных (защита от пустых ответов при больших интервалах)
            if (res.data && res.data.graphPoints) {
                setResponse(res.data);
                toast.success('Расчет выполнен успешно');
            } else {
                toast.error('Сервер не вернул данные для графика');
            }
        } catch (err: any) {
            const msg = err.response?.data?.message || "Ошибка при связи с сервером";
            toast.error(msg);
        } finally {
            setLoading(false);
        }
    };

    const handleFileLoaded = (data: IntegrationRequest) => {
        setRequest(data);
        setResponse(null);
    };

    return (
        <div className="min-h-screen bg-slate-50 pb-12 font-sans text-slate-800">
            <Header />

            <main className="container mx-auto px-4 max-w-6xl">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in duration-500">

                    {/* ЛЕВАЯ КОЛОНКА */}
                    <div className="lg:col-span-5 space-y-6">
                        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                            <div className="flex items-center justify-between mb-6">
                                <h2 className="text-lg font-bold text-slate-800 tracking-tight">Конфигурация</h2>
                                <FileUpload onDataLoaded={handleFileLoaded} />
                            </div>

                            <div className="space-y-6">
                                <FunctionSelector
                                    selected={request.functionId}
                                    onChange={(id) => setRequest({...request, functionId: id})}
                                />

                                <MethodSelector
                                    selected={request.methodId}
                                    onChange={(id) => setRequest({...request, methodId: id})}
                                />

                                <IntegrationForm
                                    request={request}
                                    setRequest={setRequest}
                                    onCalculate={handleCalculate}
                                    loading={loading}
                                />
                            </div>
                        </div>
                    </div>

                    {/* ПРАВАЯ КОЛОНКА */}
                    <div className="lg:col-span-7 space-y-6">
                        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 min-h-[500px] flex flex-col">
                            {response ? (
                                <div className="animate-in zoom-in-95 duration-300">
                                    <div className="border-b border-slate-100 pb-4 mb-4 flex justify-between items-center">
                                        <h2 className="text-sm font-black uppercase tracking-[0.2em] text-slate-400">
                                            Результат вычислений
                                        </h2>
                                    </div>

                                    {/* БЛОК ГРАФИКА С ПРОВЕРКОЙ */}
                                    {response.graphPoints && response.graphPoints.length > 0 ? (
                                        <IntegrationChart
                                            points={response.graphPoints}
                                            a={request.a}
                                            b={request.b}
                                        />
                                    ) : (
                                        /* ЗАГЛУШКА ЕСЛИ ГРАФИК НЕ ПОСТРОИЛСЯ */
                                        <div className="h-[300px] my-4 flex flex-col items-center justify-center bg-slate-50 border border-dashed border-slate-200 rounded-xl px-10 text-center">
                                            <div className="bg-amber-100 p-3 rounded-full mb-3">
                                                <Info size={24} className="text-amber-600" />
                                            </div>
                                            <h3 className="text-slate-700 font-bold text-sm mb-1">Визуализация недоступна</h3>
                                            <p className="text-slate-500 text-[11px] leading-relaxed">
                                                Интервал слишком велик или функция имеет особенности.
                                                Числовые результаты представлены в таблице ниже.
                                            </p>
                                        </div>
                                    )}

                                    {/* ТАБЛИЦА РЕЗУЛЬТАТОВ (всегда показываем, если есть response) */}
                                    <div className="mt-6">
                                        <ResultsTable response={response} />
                                    </div>
                                </div>
                            ) : (
                                /* СОСТОЯНИЕ ОЖИДАНИЯ */
                                <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
                                    <div className="bg-slate-50 p-6 rounded-full mb-4 border border-slate-100">
                                        <Calculator size={40} className="opacity-20 text-indigo-600" />
                                    </div>
                                    <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-300 text-center max-w-[250px]">
                                        {loading ? 'Идут вычисления...' : 'Ожидание параметров для расчета'}
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </main>
        </div>
    );
};

export default IntegrationPage;
